# Independently authored native observations for unfinished formatC optional behavior.
# These assertions are not included in the bounded compatibility claim.
# Windows GNU R formatC/sprintf round the following exact input differently at 22 digits.
# Independent binary64 rational expansion gives
# 0.000000999999999999999954748111825886258685613938723690807819366455078125,
# hence 9.999999999999999547481e-07; this host reports ...547237e-07.
# Pin the observed input bits so this cannot be mistaken for a parsing difference.
# Normative Linux execution and the numerical-deviation policy remain deferred.
stopifnot(identical(writeBin(1e-6,raw(),size=8,endian="big"),as.raw(c(0x3e,0xb0,0xc6,0xf7,0xa0,0xb5,0xed,0x8d))))
check<-function(name,expr){tryCatch(cat(if(isTRUE(force(expr)))"PASS" else "FAIL",name,"\n"),error=function(e)cat("ERROR",name,conditionMessage(e),"\n"))}
check("fg finite nonfinite",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(0,1.25,-1.25,12345,1e-5,NA_real_,NaN,Inf,-Inf),format="fg",digits=2)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("0", "1.2", "-1.2", "12345", "0.00001", "  NA",
" NaN", " Inf", "-Inf"), warnings = character(0))))
check("g digits 22",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(0,1.25,2.5,3.5,1/3,1e12,1e-6),format="g",digits=22)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("                      0", "                   1.25",
"                    2.5", "                    3.5", "0.3333333333333333148296",
"          1000000000000", "9.999999999999999547237e-07"), warnings = character(0))))
check("big and small marks",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(12345.123456,-1234567.123456),format="f",digits=6,big.mark=",",small.mark="_")}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("12,345.12345_6", "-1,234,567.12345_6"), warnings = character(0))))
check("zero replacement",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(-1,1,0.001,1)/c(Inf,Inf,1,1),format="f",digits=2,zero.print="zero")}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("zero", "zero", "zero", "1.00"), warnings = character(0))))
check("zero replacement keeps sign",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(-1,1)/Inf,format="f",digits=2,zero.print="zero",replace.zero=FALSE)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("-zero", "zero"), warnings = character(0))))
check("drop trailing zeros",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(0,1,1.2,1.25,1e8),format="f",digits=3,drop0trailing=TRUE)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("0", "1", "1.2", "1.25", "100000000"), warnings = character(0))))
check("preserve common",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(1.2,10000.2),format="f",digits=1,big.mark=",",preserve.width="common")}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("     1.2", "10,000.2"), warnings = character(0))))
check("preserve none",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(1.2,10000.2),format="f",digits=1,big.mark=",",preserve.width="none")}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("1.2", "10,000.2"), warnings = character(0))))
check("fg fixed significance",identical(local({err<-function(expr)tryCatch({expr;NULL},error=conditionMessage);warnings<-character();value<-withCallingHandlers(local({formatC(c(0,1.23456,123.456,123456,1e-5,9.999,-0.001),format="fg",digits=3,width=0)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")});list(value=value,warnings=warnings)}),list(value = c("0", "1.23", "123", "123456", "0.00001", " 10",
"-0.001"), warnings = character(0))))
